@lru_cache(None)
def fin(p):
    """Момент окончания процесса p: старт — когда закончатся все, от кого он зависит."""
    return T[p] + max((fin(q) for q in D[p]), default=0)

total = max(fin(p) for p in T)
after = {p: [] for p in T}
for p in T:
    for q in D[p]:
        after[q].append(p)

from functools import lru_cache

@lru_cache(None)
def tail(p):
    """Сколько ещё времени нужно после окончания p до конца цепочек, которые от него зависят."""
    return max((T[r] + tail(r) for r in after[p]), default=0)

print(sum(1 for p in T if fin(p) + tail(p) < total))
